  col <- c("A" = "red", "B" = "green", "C" = "blue")
  cols <- function(x) ggplot_build(x)@data[[1]][, "fill"]
  df <- data_frame(x = letters[1:3], y = LETTERS[1:3], z = factor(c(1, 2, 3)))
  .plot("test-scale-manual.R: generic scale can be used in place of aesthetic-specific scales #2", p1 <- ggplot(df, aes(z, z, shape = x, color = y, alpha = z)) +
