      scale_alpha_manual(values = c(0.2, 0.4, 0.6)))
  .plot("test-scale-manual.R: generic scale can be used in place of aesthetic-specific scales #3", p2 <- ggplot(df, aes(z, z, shape = x, color = y, alpha = z)) +
      scale_discrete_manual(aesthetics = "shape", values = 1:3) +
